function errorRate(errors, sample) {
  return errors / sample;
}

function isBad(rate, threshold) {
  return rate >= threshold;
}

function hasEnoughData(sample, min) {
  return sample >= min;
}

function failedRequests(rpm, ratePercent, minutes) {
  return Math.round((rpm * minutes * ratePercent) / 100);
}

function nextBadCount(count, windowIsBad) {
  return windowIsBad ? count + 1 : 0;
}

function isSevere(errors, sample, severeRate) {
  return errors / sample >= severeRate;
}

function allBad(statuses) {
  return statuses.length > 0 && statuses.every((s) => s === "bad");
}

function lastStatus(statuses) {
  if (statuses.length === 0) return "none";
  return statuses[statuses.length - 1];
}

function classifyWindow(errors, sample) {
  if (sample < 50) return "insufficient-data";
  const rate = errors / sample;
  if (rate >= 0.25) return "severe";
  if (rate >= 0.05) return "bad";
  return "good";
}

function shouldRollback(statuses) {
  if (statuses.length === 0) return false;
  if (statuses[statuses.length - 1] === "severe") return true;
  const lastThree = statuses.slice(-3);
  return lastThree.length === 3 && lastThree.every((s) => s === "bad");
}

function rollbackMinute(statuses, needed) {
  let run = 0;
  for (let i = 0; i < statuses.length; i++) {
    run = statuses[i] === "bad" ? run + 1 : 0;
    if (run === needed) return i + 1;
  }
  return -1;
}

function updateCounters(state, status) {
  if (status === "bad") return { bad: state.bad + 1, good: 0 };
  if (status === "good") return { bad: 0, good: state.good + 1 };
  return { bad: state.bad, good: state.good };
}
